import { useEffect, useId, useRef } from 'react';
import './MasterDetailDialog.css';
export interface Item { id: string; name: string; summary: string; metadata: readonly { label: string; value: string }[] }
export function MasterDetailDialog({ open, items, selectedId, onSelect, onClose, onConfirm }: { open: boolean; items: readonly Item[]; selectedId: string | null; onSelect: (id: string) => void; onClose: () => void; onConfirm: (id: string) => void }) {
  const ref = useRef<HTMLDialogElement>(null);
  const id = useId();
  const item = items.find(candidate => candidate.id === selectedId);
  useEffect(() => { const dialog = ref.current!; if (open && !dialog.open) { const previous = document.activeElement as HTMLElement | null; dialog.showModal(); return () => { dialog.close(); previous?.focus(); }; } if (!open && dialog.open) dialog.close(); }, [open]);
  return <dialog ref={ref} className="master-dialog" aria-labelledby={id + '-title'} aria-describedby={id + '-summary'} onCancel={event => { event.preventDefault(); onClose(); }}>
    <div className="master-dialog-content"><header><h1 id={id + '-title'}>Choose an item</h1><p id={id + '-summary'}>Select an item to review its details before continuing.</p></header>
    <div className="master-detail"><fieldset className="master-list"><legend>Items</legend>{items.length ? items.map(entry => <label key={entry.id}><input type="radio" name={id + '-selection'} checked={selectedId === entry.id} onChange={() => onSelect(entry.id)}/><span>{entry.name}</span></label>) : <p>No items available.</p>}</fieldset>
    <section className="item-detail" aria-labelledby={id + '-detail'}>{item ? <><h2 id={id + '-detail'}>{item.name}</h2><p>{item.summary}</p><dl>{item.metadata.map((field, index) => <div key={index}><dt>{field.label}</dt><dd>{field.value}</dd></div>)}</dl></> : <><h2 id={id + '-detail'}>Item details</h2><p>Select an item to inspect it.</p></>}</section></div>
    <footer><button type="button" onClick={onClose}>Cancel</button><button type="button" disabled={!item} onClick={() => { if (item) onConfirm(item.id); }}>Use selected item</button></footer></div>
  </dialog>;
}

