.master-dialog { width: min(52rem, calc(100vw - 2rem)); max-height: calc(100dvh - 2rem); margin: auto; padding: 0; border: 1px solid #b4bbc7; border-radius: .6rem; overflow: auto; color: #20232a; background: white; }
.master-dialog::backdrop { background: rgb(0 0 0 / .45); }
.master-dialog-content { padding: 1.5rem; overflow-wrap: anywhere; }
.master-detail { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 2fr); gap: 1.5rem; }
.master-list { min-width: 0; padding: .75rem; border: 1px solid #b4bbc7; }
.master-list label { display: flex; align-items: baseline; gap: .5rem; padding: .65rem .25rem; cursor: pointer; }
.item-detail { min-width: 0; }
.item-detail h2 { margin-top: 0; }
.item-detail dl div { margin-block: .75rem; }
.item-detail dt { font-weight: 600; }
.item-detail dd { margin: .25rem 0 0; white-space: pre-wrap; }
.master-dialog footer { display: flex; justify-content: flex-end; flex-wrap: wrap; gap: .75rem; margin-top: 1.5rem; }
.master-dialog button { font: inherit; padding: .6rem .9rem; }
.master-dialog :focus-visible { outline: 3px solid #205ed8; outline-offset: 2px; }
@media (max-width: 600px) { .master-detail { grid-template-columns: minmax(0, 1fr); } .master-dialog-content { padding: 1rem; } }
